class Solution {
    public double combinedMedian(int[] a, int[] b) {
        int total = a.length + b.length, i = 0, j = 0, prev = 0, cur = 0;
        for (int t = 0; t <= total / 2; t++) {
            prev = cur;
            if (j == b.length || (i < a.length && a[i] <= b[j])) cur = a[i++];
            else cur = b[j++];
        }
        return total % 2 == 1 ? cur : (prev + cur) / 2.0;
    }
}

