double combinedMedian(int* a, int aSize, int* b, int bSize) {
    if (aSize > bSize) return combinedMedian(b, bSize, a, aSize);
    int m = aSize, n = bSize;
    int half = (m + n + 1) / 2, lo = 0, hi = m;
    while (1) {
        int i = (lo + hi) / 2, j = half - i;
        long long aLeft = i > 0 ? a[i - 1] : LLONG_MIN;
        long long aRight = i < m ? a[i] : LLONG_MAX;
        long long bLeft = j > 0 ? b[j - 1] : LLONG_MIN;
        long long bRight = j < n ? b[j] : LLONG_MAX;
        if (aLeft <= bRight && bLeft <= aRight) {
            long long leftMax = aLeft > bLeft ? aLeft : bLeft;
            if ((m + n) % 2 == 1) return (double) leftMax;
            long long rightMin = aRight < bRight ? aRight : bRight;
            return (leftMax + rightMin) / 2.0;
        }
        if (aLeft > bRight) hi = i - 1;
        else lo = i + 1;
    }
}
